con:config.con:script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

def p=testRunner.testCase.testSuite.project
String caseId=testRunner.testCase.getPropertyValue('CASE_ID') ?: testRunner.testCase.name
String sourceStatus=testRunner.testCase.getPropertyValue('SOURCE_STATUS') ?: ''
def step=testRunner.testCase.getTestStepByName('02 Execute REST Request')
def rr=step.getTestRequest()
def resp=rr.getResponse()
int status=resp?.getStatusCode() ?: -1
String result=step.getPropertyValue('Response') ?: resp?.getContentAsString() ?: ''
String sent=rr.getRequestContent() ?: ''
String folder=(p.getPropertyValue('AUHN_EVIDENCE_DIR') ?: '').trim()
if (!folder) folder=new File(System.getProperty('user.home'),'Downloads/AUHN_Wave3_Evidence').absolutePath
def dir=new File(folder);assert dir.exists() || dir.mkdirs() : 'Cannot create evidence directory'
new File(dir,caseId+'.request.json').setText(sent,'UTF-8')
new File(dir,caseId+'.response.json').setText(result,'UTF-8')
def evidence=[caseId:caseId,runAt:new Date().toString(),httpStatus:status,ruleStatus:sourceStatus,
              baselineStatus:'STRUCTURAL_ONLY_NOT_A_PARITY_PASS',actualRoute:'',actualReferrals:[]]
try {
 assert status in [200,201,202] : 'Unexpected HTTP status '+status
 def parsed=new JsonSlurper().parseText(result)
 assert parsed instanceof Map && parsed.auDecisionArea instanceof Map : 'Missing auDecisionArea response object'
 def d=parsed.auDecisionArea
 def reasons=(d.wuc121_routing_reasons instanceof List)?d.wuc121_routing_reasons:[]
 def actual=reasons.findAll{it instanceof Map && it.wuc121_rsn_code!=null && it.wuc121_rsn_code.toString().trim() && it.wuc121_rsn_code.toString().trim().padLeft(3,'0')!='000'}
 def tuples=actual.collect{a-> [code:a.wuc121_rsn_code.toString().trim().padLeft(3,'0'),driver:(a.wuc121_rsn_driver_number?:'').toString().trim(),vehicle:(a.wuc121_rsn_vehicle_number?:'').toString().trim()]}
 evidence.actualRoute=(d.wuc121_routing_destination?:'').toString().trim()
 evidence.actualReferrals=tuples
 String baselineDir=(p.getPropertyValue('AION_BASELINE_DIR')?:'').trim()
 File baseline=baselineDir ? new File(baselineDir,caseId+'.json') : null
 boolean strict=(p.getPropertyValue('REQUIRE_AION_BASELINE')?:'NO').equalsIgnoreCase('YES')
 if (baseline!=null && baseline.isFile()){
   def gold=new JsonSlurper().parse(baseline,'UTF-8')
   assert gold.routingDestination!=null && gold.referrals instanceof List : 'Baseline format must have routingDestination and referrals list'
   def expected=gold.referrals.collect{a->[code:a.code.toString().trim().padLeft(3,'0'),driver:(a.driver?:'').toString().trim(),vehicle:(a.vehicle?:'').toString().trim()]}
   assert evidence.actualRoute==gold.routingDestination : 'Routing mismatch: '+evidence.actualRoute+' != '+gold.routingDestination
   // Strict tuple order including driver/vehicle may be enabled when the AION baseline carries those fields.
   assert tuples.collect{it.code}==expected.collect{it.code}: 'Ordered referral code sequence differs from AION'
   if (gold.requireTupleMatch == true){
      assert tuples==expected : 'Referral tuple mismatch compared to AION'
   }
   evidence.baselineStatus='AION_BASELINE_PARITY_PASS'
 } else if (strict){
   assert false : 'AION baseline missing for '+caseId+'; STRICT mode requires '+caseId+'.json'
 } else {
   log.warn('STRUCTURAL_ONLY - NOT A PARITY PASS: '+caseId+'; attach AION baseline for business assertions')
 }
} finally {
 new File(dir,caseId+'.evidence.json').setText(JsonOutput.prettyPrint(JsonOutput.toJson(evidence)),'UTF-8')
}

